#include <bits/stdc++.h>
using namespace std;
using ll = long long;

int main() {
    int N, K;
    ll L;

    cin >> N >> L;
    cin >> K;

    vector<ll> A(N);

    for (int i = 0; i < N; i++) {
        cin >> A[i];
    }

    auto check = [&](ll x) {
        ll prev = 0;
        int cnt = 0;

        for (int i = 0; i < N; i++) {
            // 今切ったとき
            // 前のピース >= x
            // 最後のピース >= x
            if (A[i] - prev >= x && L - A[i] >= x) {
                cnt++;
                prev = A[i];
            }
        }

        return cnt >= K;
    };

    ll low = 0;
    ll high = L + 1;

    while (high - low > 1) {
        ll mid = (low + high) / 2;

        if (check(mid)) {
            low = mid;
        } else {
            high = mid;
        }
    }

    cout << low << endl;
}

